(5832917, 849548, 110023, '<td valign="top">This made me hungry...and thirsty :) Very nice arrangement!</td>', 'This made me hungry...and thirsty :) Very nice arrangement!', '2010-01-25 16:05:54.000000', NULL, 1),
(5832921, 848730, 110023, '<td valign="top">Very well done in b&amp;w!</td>', 'Very well done in b&w!', '2010-01-25 16:07:11.000000', NULL, 1),
