(5832929, 849396, 42013, '<td valign="top">has the makings of an AJHOpp! Love the natural light!</td>', 'has the makings of an AJHOpp! Love the natural light!', '2010-01-25 16:09:20.000000', NULL, 1),
(5832942, 849484, 10785, '<td valign="top">Nice set up on this one. It looks like you tried to use complimentary colors to make this photo pop. Just looking at a simple color wheel, purple is complimentary for yellow, so nice selection for your backdrop. But red is complimentary for green. I have no idea how you would make purple and red work together though so you did better than I could. One interesting thing to note is that I think the blue bucket is reflecting off the yellow lemon, making it green.</td>', 'Nice set up on this one. It looks like you tried to use complimentary colors to make this photo pop. Just looking at a simple color wheel, purple is complimentary for yellow, so nice selection for your backdrop. But red is complimentary for green. I have no idea how you would make purple and red work together though so you did better than I could. One interesting thing to note is that I think the blue bucket is reflecting off the yellow lemon, making it green.', '2010-01-25 16:15:41.000000', NULL, 1),
(5832951, 849607, 110023, '<td valign="top">Beautiful! Love the colors and arrangement.</td>', 'Beautiful! Love the colors and arrangement.', '2010-01-25 16:22:24.000000', NULL, 1),
(5833073, 849628, 14867, '<td valign="top">Pure and beautiful, so simple, so perfect. Impressive.</td>', 'Pure and beautiful, so simple, so perfect. Impressive.', '2010-01-25 17:33:18.000000', NULL, 1),
