(5834953, 849023, 30049, '<td valign="top">Woah!  Radiated fruit!  Different for sure.  Seems a bit over the top for me with the post-processing (Topaz perhaps?).  Good luck in the challenge.</td>', 'Woah!  Radiated fruit!  Different for sure.  Seems a bit over the top for me with the post-processing (Topaz perhaps?).  Good luck in the challenge.', '2010-01-26 15:54:00.000000', NULL, 1),
(5834957, 849068, 30049, '<td valign="top">It''s a pear convention!  :-)  I think you could have made a better selling point with the left five and given the viewer more detail.</td>', 'It''s a pear convention!  :-)  I think you could have made a better selling point with the left five and given the viewer more detail.', '2010-01-26 15:54:45.000000', NULL, 1),
(5834958, 848771, 30049, '<td valign="top">Look, it''s wet!  :-)  I like the lighting effect you went for here.  Losing detail on the back side of the fruit is minimizing the impact.  What was your aperture on this...F3.5 or F4?  I''d have gone F8 minimum to get detail all the way thru.  JMO of course.  Good luck in the challenge.</td>', 'Look, it''s wet!  :-)  I like the lighting effect you went for here.  Losing detail on the back side of the fruit is minimizing the impact.  What was your aperture on this...F3.5 or F4?  I''d have gone F8 minimum to get detail all the way thru.  JMO of course.  Good luck in the challenge.', '2010-01-26 15:56:46.000000', NULL, 1),
(5834964, 849674, 30049, '<td valign="top">O...K...a..y..y.y.  Good luck with that.  :-)  Cute, but oh so DNMC for the masses.</td>', 'O...K...a..y..y.y.  Good luck with that.  :-)  Cute, but oh so DNMC for the masses.', '2010-01-26 15:57:53.000000', NULL, 1),
(5834967, 848700, 30049, '<td valign="top">An interesting mix of props here.  IMO it may be a little too much with the train there.  JMO of course.  Good luck!</td>', 'An interesting mix of props here.  IMO it may be a little too much with the train there.  JMO of course.  Good luck!', '2010-01-26 15:59:04.000000', NULL, 1),
(5834980, 849637, 30049, '<td valign="top">Cute.</td>', 'Cute.', '2010-01-26 16:05:57.000000', NULL, 1),
(5834988, 848971, 30049, '<td valign="top">The clarify, highlight/shadow adjustment, or Topaz treatement, really gives this photo a harsh feel.  The saturation of blues and yellow/greens are over the top a bit also.  Cute idea...just pushed a little too far in post IMO.  Good luck in the challenge.</td>', 'The clarify, highlight/shadow adjustment, or Topaz treatement, really gives this photo a harsh feel.  The saturation of blues and yellow/greens are over the top a bit also.  Cute idea...just pushed a little too far in post IMO.  Good luck in the challenge.', '2010-01-26 16:08:35.000000', NULL, 1),
(5834990, 849592, 30049, '<td valign="top">Couldn''t get to the grocery store?</td>', 'Couldn''t get to the grocery store?', '2010-01-26 16:08:37.000000', NULL, 1),
(5834991, 848157, 30049, '<td valign="top">It DOES look like stars on there now that you mention it!  :-)</td>', 'It DOES look like stars on there now that you mention it!  :-)', '2010-01-26 16:09:02.000000', NULL, 1),
(5834993, 848950, 30049, '<td valign="top">Funny.  :-P  Seems a little dark on this monitor.  Should have used a wooden bowl though instead of the glass.  :-)</td>', 'Funny.  :-P  Seems a little dark on this monitor.  Should have used a wooden bowl though instead of the glass.  :-)', '2010-01-26 16:09:46.000000', NULL, 1),
(5834994, 849577, 30049, '<td valign="top">Ho-hum.</td>', 'Ho-hum.', '2010-01-26 16:09:57.000000', NULL, 1),
(5835002, 849540, 30049, '<td valign="top">Nice detail.  Try this on a black background with some backlighting to give the edges a rim glow (to show that "hair").  This is "ok", but nothing overly exciting.  JMO of course.  Good luck.</td>', 'Nice detail.  Try this on a black background with some backlighting to give the edges a rim glow (to show that "hair").  This is "ok", but nothing overly exciting.  JMO of course.  Good luck.', '2010-01-26 16:12:43.000000', NULL, 1),
(5835003, 849573, 30049, '<td valign="top">I can''t believe it but I''m getting an emotive feeling of sadness and despair looking at this photo.  !!!  How''d you do that?!  Wonderful tones.  This gets my top "artsy" award so far.  Good luck in the challenge.</td>', 'I can''t believe it but I''m getting an emotive feeling of sadness and despair looking at this photo.  !!!  How''d you do that?!  Wonderful tones.  This gets my top "artsy" award so far.  Good luck in the challenge.', '2010-01-26 16:12:45.000000', NULL, 1),
(5835006, 849606, 30049, '<td valign="top">Nice materials in place...just a bit too soft for my taste, and the POV is somewhat flat.</td>', 'Nice materials in place...just a bit too soft for my taste, and the POV is somewhat flat.', '2010-01-26 16:13:31.000000', NULL, 1),
(5835007, 849664, 30049, '<td valign="top">Ummm....cute?</td>', 'Ummm....cute?', '2010-01-26 16:13:57.000000', NULL, 1),
(5835008, 848768, 30049, '<td valign="top">The red should be up top.  Where are you from?  :-)</td>', 'The red should be up top.  Where are you from?  :-)', '2010-01-26 16:14:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5835012, 848043, 30049, '<td valign="top">A nice arrangement.  Somewhat heavy on the post-processing touch for my taste however.  Good luck.</td>', 'A nice arrangement.  Somewhat heavy on the post-processing touch for my taste however.  Good luck.', '2010-01-26 16:15:29.000000', NULL, 1),
(5835019, 849146, 30049, '<td valign="top">Hi Michelle.  :-)  If I didn''t guess right, then pardon my intrusion.  :-)  I like the arrangement of this still life quite a bit.  The grain works fine and goes well with the leaves, table covering and background.  The rest of the post-processing treatment has given this a painterly feel, which is fun overall.  Certainly an "artistic" approach to this challenge.  Good luck!</td>', 'Hi Michelle.  :-)  If I didn''t guess right, then pardon my intrusion.  :-)  I like the arrangement of this still life quite a bit.  The grain works fine and goes well with the leaves, table covering and background.  The rest of the post-processing treatment has given this a painterly feel, which is fun overall.  Certainly an "artistic" approach to this challenge.  Good luck!', '2010-01-26 16:18:03.000000', NULL, 1),
(5835042, 849538, 30049, '<td valign="top">Hmmm.  I''m having a hard time finding anything over the top positive, nor can I find anything that seems really out of place on the down side.  A solid middle level entry then I guess, eh?  :-)   Good luck in the challenge.</td>', 'Hmmm.  I''m having a hard time finding anything over the top positive, nor can I find anything that seems really out of place on the down side.  A solid middle level entry then I guess, eh?  :-)   Good luck in the challenge.', '2010-01-26 16:32:10.000000', NULL, 1),
(5835046, 849701, 30049, '<td valign="top">Points for being clever for sure.  Overall, nice control of lighting.  BTW - what does one do for the 7th day...there''s only 6 apples.  :-)</td>', 'Points for being clever for sure.  Overall, nice control of lighting.  BTW - what does one do for the 7th day...there''s only 6 apples.  :-)', '2010-01-26 16:33:33.000000', NULL, 1),
(5835054, 849217, 30049, '<td valign="top">I like the reflections, especially on the background.  I know you left the extra lower space for the full reflection of the cup, but it seems like this would be more balanced with the cup closer to the bottom of the photo.  Just an observation...  Fruit wise...that''s a very small bit of fruit.  Good luck with that.  :-)</td>', 'I like the reflections, especially on the background.  I know you left the extra lower space for the full reflection of the cup, but it seems like this would be more balanced with the cup closer to the bottom of the photo.  Just an observation...  Fruit wise...that''s a very small bit of fruit.  Good luck with that.  :-)', '2010-01-26 16:36:26.000000', NULL, 1),
(5835055, 849453, 30049, '<td valign="top">Not quite sure what you did in post-processing, but this doesn''t really look like a photo anymore.</td>', 'Not quite sure what you did in post-processing, but this doesn''t really look like a photo anymore.', '2010-01-26 16:36:29.000000', NULL, 1),
(5835065, 849570, 7711, '<td valign="top">while very pretty fruit, the composition lacks any meaning. I mean, its not telling us any story and maybe that''s a lot to ask of a couple of raspberries, but I think without a background other objects in the still life, its rather..lifeless. :(</td>', 'while very pretty fruit, the composition lacks any meaning. I mean, its not telling us any story and maybe that''s a lot to ask of a couple of raspberries, but I think without a background other objects in the still life, its rather..lifeless. :(', '2010-01-26 16:48:37.000000', NULL, 1),
(5835066, 847800, 7711, '<td valign="top">a very classic composition style, if not a bit busy. I like the lighting, though it comes off a tiny bit harsh on a couple of the shinier apples. A black blackground would have helped with the busy-ness.</td>', 'a very classic composition style, if not a bit busy. I like the lighting, though it comes off a tiny bit harsh on a couple of the shinier apples. A black blackground would have helped with the busy-ness.', '2010-01-26 16:49:56.000000', NULL, 1),
(5835067, 849574, 7711, '<td valign="top">gorgeous texture captured on the pear. The plain composition suits the subject very well. I like that the wood grain is still visible in the foreground..gives us some textural contrast.</td>', 'gorgeous texture captured on the pear. The plain composition suits the subject very well. I like that the wood grain is still visible in the foreground..gives us some textural contrast.', '2010-01-26 16:50:55.000000', NULL, 1),
(5835068, 849484, 7711, '<td valign="top">fruit arrangement is fun, but the purple backdrop is just too distracting. Its messy and the colour of it takes away from the richness of the fruits'' natural colours and makes them look garish in comparision.</td>', 'fruit arrangement is fun, but the purple backdrop is just too distracting. Its messy and the colour of it takes away from the richness of the fruits'' natural colours and makes them look garish in comparision.', '2010-01-26 16:51:57.000000', NULL, 1),
(5835071, 849702, 7711, '<td valign="top">the border is distracting, and the image is not sharp all over (or even enough). Its ok to have soft focus, or even just some part of the image that is in focus if the out of focus areas frame the intended subject, but the fruit is not sharp enough (like the citrus especially) and its very distracting. The rocks are also a strange juxtaposition, but it doesn''t quite work here. Plus we''ve lost a bit of the pineapple top, and that''s very distracting as well.</td>', 'the border is distracting, and the image is not sharp all over (or even enough). Its ok to have soft focus, or even just some part of the image that is in focus if the out of focus areas frame the intended subject, but the fruit is not sharp enough (like the citrus especially) and its very distracting. The rocks are also a strange juxtaposition, but it doesn''t quite work here. Plus we''ve lost a bit of the pineapple top, and that''s very distracting as well.', '2010-01-26 16:54:09.000000', NULL, 1),
(5835073, 849641, 7711, '<td valign="top">pure bliss. A good use of lighting and compositional framing.</td>', 'pure bliss. A good use of lighting and compositional framing.', '2010-01-26 16:54:52.000000', NULL, 1),
(5835076, 849709, 7711, '<td valign="top">edges seem a bit hard, like a line drawing, but I like that sort of unreal look about the fruit. Nice background as well.</td>', 'edges seem a bit hard, like a line drawing, but I like that sort of unreal look about the fruit. Nice background as well.', '2010-01-26 16:55:43.000000', NULL, 1),
(5835077, 849533, 7711, '<td valign="top">the focus gets a bit lost near the top part of the pear, but otherwise, fun composition with good use of negative space.</td>', 'the focus gets a bit lost near the top part of the pear, but otherwise, fun composition with good use of negative space.', '2010-01-26 16:56:33.000000', NULL, 1),
(5835078, 849146, 7711, '<td valign="top">looks like a drawing or a painting. Very interesting use of lighting as well to highlight the curves of the fruit.</td>', 'looks like a drawing or a painting. Very interesting use of lighting as well to highlight the curves of the fruit.', '2010-01-26 16:57:12.000000', NULL, 1),
(5835082, 849629, 7711, '<td valign="top">great composition, but it could really use more negative space to help frame the peaches better. Nice lighting, however and lovely background choice.</td>', 'great composition, but it could really use more negative space to help frame the peaches better. Nice lighting, however and lovely background choice.', '2010-01-26 16:58:04.000000', NULL, 1),
(5835085, 849504, 7711, '<td valign="top">I think these pears have a lot of character, colour and texture that are lost in this black and white presentation. The bowl fares well in monochrome, but I think the pears are suffering as their warmth and personality are muted by the monochromatic colouring.</td>', 'I think these pears have a lot of character, colour and texture that are lost in this black and white presentation. The bowl fares well in monochrome, but I think the pears are suffering as their warmth and personality are muted by the monochromatic colouring.', '2010-01-26 16:59:29.000000', NULL, 1),
(5835086, 848700, 7711, '<td valign="top">cute composition, but the background is too bright and distracts from the actual subjects.</td>', 'cute composition, but the background is too bright and distracts from the actual subjects.', '2010-01-26 17:00:04.000000', NULL, 1),
(5835089, 847840, 7711, '<td valign="top">a smaller light off to the lower right would have helped bring out the curves of the pears which I think would have improved this composition quite a bit. Its a nice use of negative space, however and the red wool is a lovely contrast.</td>', 'a smaller light off to the lower right would have helped bring out the curves of the pears which I think would have improved this composition quite a bit. Its a nice use of negative space, however and the red wool is a lovely contrast.', '2010-01-26 17:01:03.000000', NULL, 1),
(5835093, 849714, 7711, '<td valign="top">ooh the texture!!! Just magnificent. Awesome tonal presentation as well. Great framing and composition. Well done!</td>', 'ooh the texture!!! Just magnificent. Awesome tonal presentation as well. Great framing and composition. Well done!', '2010-01-26 17:01:47.000000', NULL, 1),
(5835095, 849627, 7711, '<td valign="top">object arrangement is fine, but the use of both brick and wood are distracting elements to the composition.</td>', 'object arrangement is fine, but the use of both brick and wood are distracting elements to the composition.', '2010-01-26 17:02:49.000000', NULL, 1),
(5835099, 849685, 7711, '<td valign="top">crop is too tight for this; it looks too busy. Lighting is also a bit harsh on the apples.</td>', 'crop is too tight for this; it looks too busy. Lighting is also a bit harsh on the apples.', '2010-01-26 17:04:40.000000', NULL, 1),
(5835100, 849573, 7711, '<td valign="top">awesome use of the monochromatic technique. You''ve maintained the texture and warmth of the pears but given them a dramatic look.</td>', 'awesome use of the monochromatic technique. You''ve maintained the texture and warmth of the pears but given them a dramatic look.', '2010-01-26 17:05:45.000000', NULL, 1),
(5835101, 849159, 7711, '<td valign="top">this would have benefitted from less light overall to give it a less harsh look.</td>', 'this would have benefitted from less light overall to give it a less harsh look.', '2010-01-26 17:06:55.000000', NULL, 1),
(5835124, 847732, 7711, '<td valign="top">this is one of my favourites of the challenge. The muted tones work well with the lighting -- the high key background sets the applies off, while they are given texture through the water drops and good use of focus. 9</td>', 'this is one of my favourites of the challenge. The muted tones work well with the lighting -- the high key background sets the applies off, while they are given texture through the water drops and good use of focus. 9', '2010-01-26 17:21:28.000000', NULL, 1),
(5835127, 848557, 7711, '<td valign="top">lovely concept, but overuse of noise reduction software has taken away the texture and character from your subjects.</td>', 'lovely concept, but overuse of noise reduction software has taken away the texture and character from your subjects.', '2010-01-26 17:22:54.000000', NULL, 1),
(5835174, 849707, 103004, '<td valign="top">just beautiful 10</td>', 'just beautiful 10', '2010-01-26 17:45:04.000000', NULL, 1),
(5835193, 849505, 103004, '<td valign="top">wow this picture make me hungry...excellent 9</td>', 'wow this picture make me hungry...excellent 9', '2010-01-26 17:53:45.000000', NULL, 1),
(5835197, 849111, 103004, '<td valign="top">i like the colors</td>', 'i like the colors', '2010-01-26 17:55:18.000000', NULL, 1),
(5835561, 849566, 57447, '<td valign="top">I like how you placed the fruit in the frame.  There is some blur in the grapes but maybe it won''t hurt your score.</td>', 'I like how you placed the fruit in the frame.  There is some blur in the grapes but maybe it won''t hurt your score.', '2010-01-26 20:58:50.000000', NULL, 1),
(5835569, 848730, 57447, '<td valign="top">Superb.  Hope it scores high for you.</td>', 'Superb.  Hope it scores high for you.', '2010-01-26 21:01:14.000000', NULL, 1),
(5835573, 849675, 57447, '<td valign="top">Somewhat different but interesting.</td>', 'Somewhat different but interesting.', '2010-01-26 21:02:18.000000', NULL, 1),
(5835575, 849533, 57447, '<td valign="top">Unique composition.</td>', 'Unique composition.', '2010-01-26 21:02:57.000000', NULL, 1),
(5835578, 849671, 57447, '<td valign="top">Cheers!  Pretty still life.</td>', 'Cheers!  Pretty still life.', '2010-01-26 21:03:44.000000', NULL, 1),
(5835580, 849681, 57447, '<td valign="top">Well balanced.  I like the soft blur used.</td>', 'Well balanced.  I like the soft blur used.', '2010-01-26 21:04:47.000000', NULL, 1),
