(5835653, 849505, 57447, '<td valign="top">Aussi baguette and other things.</td>', 'Aussi baguette and other things.', '2010-01-26 21:29:06.000000', NULL, 1),
(5835670, 849707, 57447, '<td valign="top">I like your entry above the pears.  The vase, window frame and flowers are beautiful.</td>', 'I like your entry above the pears.  The vase, window frame and flowers are beautiful.', '2010-01-26 21:33:58.000000', NULL, 1),
(5835679, 848512, 57447, '<td valign="top">Should do very well.  Great balance and lighting.</td>', 'Should do very well.  Great balance and lighting.', '2010-01-26 21:35:20.000000', NULL, 1),
(5835692, 849654, 73250, '<td valign="top">I really like this...but the strawberries look out of place.</td>', 'I really like this...but the strawberries look out of place.', '2010-01-26 21:37:07.000000', NULL, 1),
(5835693, 848762, 57447, '<td valign="top">Would look good if your entry was in better focus.</td>', 'Would look good if your entry was in better focus.', '2010-01-26 21:37:19.000000', NULL, 1),
