(5836100, 849484, 56880, '<td valign="top">Excellent color contrast!</td>', 'Excellent color contrast!', '2010-01-27 00:15:52.000000', NULL, 1),
(5836145, 849111, 99413, '<td valign="top">I love the clarity of this picture. The orange on the white pops very well. one of my top 3 favorites.</td>', 'I love the clarity of this picture. The orange on the white pops very well. one of my top 3 favorites.', '2010-01-27 00:33:56.000000', NULL, 1),
(5836146, 849396, 99413, '<td valign="top">Lots of pear pictures going for this style but this one is my favorite. Great textures and the I love the slightly muted colours. One of my top 3 favorites.</td>', 'Lots of pear pictures going for this style but this one is my favorite. Great textures and the I love the slightly muted colours. One of my top 3 favorites.', '2010-01-27 00:34:44.000000', NULL, 1),
(5836151, 849503, 99413, '<td valign="top">This shot is one of my top 3 favorites. The ice and limes contrast great with the black background. Very sharp aswell, I feel as if I could reach out and touch it. The only thing that I would change (and this is being extremely picky) is that I would like to see more detail in the pieces of the sliced lime.</td>', 'This shot is one of my top 3 favorites. The ice and limes contrast great with the black background. Very sharp aswell, I feel as if I could reach out and touch it. The only thing that I would change (and this is being extremely picky) is that I would like to see more detail in the pieces of the sliced lime.', '2010-01-27 00:35:26.000000', NULL, 1),
(5836152, 849502, 99413, '<td valign="top">Great colours. The shot reminds me of one by Eyewave, or <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=49109" rel="nofollow" target="_blank">h2</a> now, so I''m guessing it''s you? or maybe not haha. <br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=445022" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/610/120/Copyrighted_Image_Reuse_Prohibited_445022.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/610/120/Copyrighted_Image_Reuse_Prohibited_445022.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/610/120/Copyrighted_Image_Reuse_Prohibited_445022.jpg"/></a> <br/> <br/>Anyways, I gave this a 9.</td>', 'Great colours. The shot reminds me of one by Eyewave, or  h2 now, so I''m guessing it''s you? or maybe not haha.    Anyways, I gave this a 9.', '2010-01-27 00:35:53.000000', NULL, 1),
(5836397, 849701, 110108, '<td valign="top">good concept</td>', 'good concept', '2010-01-27 03:20:30.000000', NULL, 1),
