(5845493, 849674, 65234, '<td valign="top">I know peanuts aren''t true nuts and I''m too lazy to Google it, so I''ll assume they are indeed fruits.  I like the diagonal on the composition and the DOF.  A bit noisy on my screen.</td>', 'I know peanuts aren''t true nuts and I''m too lazy to Google it, so I''ll assume they are indeed fruits.  I like the diagonal on the composition and the DOF.  A bit noisy on my screen.', '2010-01-31 16:28:51.000000', NULL, 1),
(5845509, 848697, 65234, '<td valign="top">Not really my idea of a still life.  A bit too much action, even if it is stopped.</td>', 'Not really my idea of a still life.  A bit too much action, even if it is stopped.', '2010-01-31 16:37:28.000000', NULL, 1),
