(5845713, 849725, 30049, '<td valign="top">Nice , soft, painterly feel to this.  Quite unique in this challenge.  Well done.</td>', 'Nice , soft, painterly feel to this.  Quite unique in this challenge.  Well done.', '2010-01-31 20:59:55.000000', NULL, 1),
(5845722, 849147, 30049, '<td valign="top">I like the pail.  Lighting is harsh.  Could use more DOF...I''d like to see the front fruit in focus.  All JMO of course.  :-)  Good luck.</td>', 'I like the pail.  Lighting is harsh.  Could use more DOF...I''d like to see the front fruit in focus.  All JMO of course.  :-)  Good luck.', '2010-01-31 21:08:10.000000', NULL, 1),
