(5845734, 849656, 30049, '<td valign="top">The pomegranate seems out of place, and it''s not in focus.  I do like the wood grain.  Good luck.</td>', 'The pomegranate seems out of place, and it''s not in focus.  I do like the wood grain.  Good luck.', '2010-01-31 21:19:06.000000', NULL, 1),
(5845743, 849496, 30049, '<td valign="top">Nice detail and lighting...this would be stronger IMO with a square crop (losing some of the top  portion).  Overall, nicely done.  Good luck.</td>', 'Nice detail and lighting...this would be stronger IMO with a square crop (losing some of the top  portion).  Overall, nicely done.  Good luck.', '2010-01-31 21:28:04.000000', NULL, 1),
(5845752, 849500, 30049, '<td valign="top">This is different, and unique.  Seems a little washed out/pale for me and the center is a little soft.  All JMO of course.  :-)  Good luck.</td>', 'This is different, and unique.  Seems a little washed out/pale for me and the center is a little soft.  All JMO of course.  :-)  Good luck.', '2010-01-31 21:34:24.000000', NULL, 1),
