(5845792, 849724, 67697, '<td valign="top">I saw this and my first thought was "country kitchen still life".  Simple and interesting.</td>', 'I saw this and my first thought was "country kitchen still life".  Simple and interesting.', '2010-01-31 22:01:24.000000', NULL, 1),
(5845794, 849502, 81362, '<td valign="top">Striking geometry, very different than the old Dutch painter approach to still life. High score for graphic quality and originality, minor deduction for slight glare.</td>', 'Striking geometry, very different than the old Dutch painter approach to still life. High score for graphic quality and originality, minor deduction for slight glare.', '2010-01-31 22:02:12.000000', NULL, 1),
(5845795, 849551, 67697, '<td valign="top">My impression of a classic still life makes subtle use of natural light or soft light.  This seems like a flash was used or a hard light - and that seems to have made you lose some of the natural detail that I''d expect to see in this category.</td>', 'My impression of a classic still life makes subtle use of natural light or soft light.  This seems like a flash was used or a hard light - and that seems to have made you lose some of the natural detail that I''d expect to see in this category.', '2010-01-31 22:03:31.000000', NULL, 1),
(5845797, 848170, 67697, '<td valign="top">The mutued colors are wonderful.  I''d like to have seen the front pear in focus because it seems to draw attention away from the other fruits.</td>', 'The mutued colors are wonderful.  I''d like to have seen the front pear in focus because it seems to draw attention away from the other fruits.', '2010-01-31 22:05:01.000000', NULL, 1),
